from alembic import context
from sqlalchemy import create_engine

from app.config import get_settings
from app.memory.models import Base

target_metadata = Base.metadata


def _sync_url() -> str:
    return get_settings().database_url.replace("+aiosqlite", "").replace("+asyncpg", "")


def include_object(obj, name, type_, reflected, compare_to):  # type: ignore[no-untyped-def]
    # FTS5 virtual + shadow tables are managed by hand, never autogenerated/dropped
    return not (type_ == "table" and name and name.startswith("script_fts"))


def run_migrations_online() -> None:
    engine = create_engine(_sync_url())
    with engine.connect() as conn:
        context.configure(connection=conn, target_metadata=target_metadata, render_as_batch=True,
            include_object=include_object,
        )
        with context.begin_transaction():
            context.run_migrations()


run_migrations_online()
